WITH performance_reviews AS (SELECT "wren_src_performance_reviews".performance_score AS performance_score, "wren_src_performance_reviews".review_date AS review_date FROM (SELECT performance_reviews.performance_score, performance_reviews.review_date FROM (SELECT __source.performance_score AS performance_score, __source.review_date AS review_date FROM hr.performance_reviews AS __source) AS performance_reviews) AS "wren_src_performance_reviews") SELECT AVG(performance_score) AS average_performance FROM performance_reviews WHERE review_date = CAST('2024-09-30' AS DATE)